B1='("Leukemia, Myeloid, Acute"[Mesh] OR "Precursor Cell Lymphoblastic Leukemia-Lymphoma"[Mesh] OR "Leukemia, Promyelocytic, Acute"[Mesh] OR "acute leukemia*"[tiab] OR "acute leukaemia*"[tiab] OR "acute myeloid leukemia"[tiab] OR "acute myeloid leukaemia"[tiab] OR "acute myelogenous leukemia"[tiab] OR "acute lymphoblastic leukemia"[tiab] OR "acute lymphoblastic leukaemia"[tiab] OR "acute lymphocytic leukemia"[tiab] OR "acute promyelocytic leukemia"[tiab] OR "acute promyelocytic leukaemia"[tiab] OR "acute nonlymphocytic leukemia"[tiab])'
