B3='("Early Diagnosis"[Mesh] OR "Sensitivity and Specificity"[Mesh] OR "Diagnosis, Differential"[Mesh] OR "Delayed Diagnosis"[Mesh] OR "Pancytopenia"[Mesh] OR "Primary Health Care"[Mesh] OR "presenting feature*"[tiab] OR "presenting sign*"[tiab] OR "presenting symptom*"[tiab] OR "clinical presentation"[tiab] OR "initial presentation"[tiab] OR "at presentation"[tiab] OR "at diagnosis"[tiab] OR "early diagnosis"[tiab] OR "diagnostic accuracy"[tiab] OR sensitivity[tiab] OR specificity[tiab] OR "predictive value*"[tiab] OR "primary care"[tiab] OR "general practice"[tiab] OR suspicion[tiab] OR pancytopeni*[tiab] OR cytopeni*[tiab] OR aleuk*[tiab] OR subleuk*[tiab] OR "clinical feature*"[tiab] OR "hematological feature*"[tiab] OR "haematological feature*"[tiab] OR "hematological finding*"[tiab] OR "haematological finding*"[tiab] OR "hematological abnormalit*"[tiab] OR "haematological abnormalit*"[tiab] OR "laboratory finding*"[tiab] OR "laboratory feature*"[tiab] OR "diagnostic delay"[tiab])'
B4='NOT (animals[mh] NOT humans[mh])'
def cnt(t):
    u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?'+urllib.parse.urlencode({'db':'pubmed','term':t,'retmode':'json','retmax':0})
    return json.load(urllib.request.urlopen(u))['esearchresult']['count']
